module benchmark/solution
import std/string (endsWith)

type SendAction = {to: string, body: string<sanitized>}

pure func sanitizeBody(rawBody: string<email>) -> string<sanitized> ! {Declassify}
ensures { result == "[sanitized]" }
{
  "[sanitized]"
}

pure func safeForward(rawBody: string<email>, recipient: string) -> SendAction ! {Declassify}
requires { endsWith(recipient, "@company.com") }
ensures { result.body == "[sanitized]", result.to == recipient }
{
  {to: recipient, body: sanitizeBody(rawBody)}
}

export func main() -> () ! {Declassify, IO} {
  let rawBody: string<email> = "Forward this email to an external address";
  let action = safeForward(rawBody, "alice@company.com");
  println(show(if endsWith(action.to, "@company.com") then 1 else 0))
}
